+// Audit log: records every request that changes data, listed newest first.
+
+/** Appends an audit entry for a data-changing request and returns it. */
+export function recordAudit(store, { keyName, method, path, status }, { at }) {
+  store.data.audit ??= [];
+  const entry = {
+    id: store.nextId("audit"),
+    time: at,
+    keyName,
+    method,
+    path,
+    status,
+  };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Returns all audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].sort((a, b) => b.time.localeCompare(a.time) || b.id - a.id);
+}
