+// API key authentication and role-based authorization.
+import { AppError } from "../errors.js";
+
+export const ROLES = ["viewer", "cook", "manager"];
+
+/** Finds the API key record for a Bearer token, or throws 401. */
+export function authenticate(store, token) {
+  if (!token) throw new AppError("unauthorized");
+  const entry = (store.data.apiKeys ?? []).find((k) => k.key === token);
+  if (!entry) throw new AppError("unauthorized");
+  return entry;
+}
+
+/** Ensures `keyEntry` has one of `allowedRoles`, or throws 403. */
+export function authorize(keyEntry, allowedRoles) {
+  if (!allowedRoles.includes(keyEntry.role)) throw new AppError("forbidden");
+}
