+  for (const req of [
+    { method: "POST", path: "/stocktakes", body: { location: "fridge" } },
+    { method: "POST", path: `/stocktakes/${take.id}/finish` },
+    { method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 1 }] } },
+    { method: "POST", path: "/orders/3/send" },
+    { method: "POST", path: "/prices", body: { supplierId: 1, itemId: 1, priceCents: 200, validFrom: "2026-10-29" } },
+    { method: "POST", path: "/dishes", body: { name: "Bread", recipeId: 1, priceCents: 500 } },
+    { method: "PUT", path: "/items/1/allergens", body: { allergens: [] } },
+    { method: "POST", path: "/jobs/nightly" },
+    { method: "GET", path: "/audit" },
+  ]) {
+    const res = await handle({ ...req, headers: auth("cook") });
+    assert.equal(res.status, 403);
+    assert.equal(res.body.error.code, "forbidden");
+  }
+});
+
+test("audit logs every data-changing request newest first for managers", async () => {
+  let tick = NOW;
+  const store = fresh();
+  const handle = createApp(store, { clock: () => tick });
+
+  // GET and failed requests must not write audit entries.
+  await handle({ path: "/items", headers: auth("viewer") });
+  await handle({ method: "POST", path: "/orders", headers: auth("cook"), body: { supplierId: 1, lines: [{ itemId: 1, qty: 1 }] } });
+  await handle({ method: "POST", path: "/recipes/2/cook", headers: auth("cook"), body: { portions: 100 } });
+  assert.equal(store.data.audit.length, 0);
+
+  await handle({ method: "POST", path: "/recipes/1/cook", headers: auth("cook"), body: { portions: 1 } });
+  tick += 1000;
+  await handle({ method: "POST", path: "/batches/1/waste", headers: auth("cook"), body: { qty: 0.5, reason: "trim" } });
+  await handle({ method: "POST", path: "/orders", headers: auth("manager"), body: { supplierId: 1, lines: [{ itemId: 1, qty: 2 }] } });
+
+  const audit = await handle({ path: "/audit", headers: auth("manager") });
+  assert.equal(audit.status, 200);
+  assert.equal(audit.body.length, 3);
+  assert.deepEqual(
+    audit.body.map(({ keyName, method, path, status }) => ({ keyName, method, path, status })),
+    [
+      { keyName: "manager", method: "POST", path: "/orders", status: 201 },
+      { keyName: "cook", method: "POST", path: "/batches/1/waste", status: 201 },
+      { keyName: "cook", method: "POST", path: "/recipes/1/cook", status: 200 },
+    ],
+  );
+  assert.equal(audit.body[0].time, new Date(NOW + 1000).toISOString());
+  assert.equal(audit.body[2].time, new Date(NOW).toISOString());
+});
+
